package com.tapdata.tm.proxyprocess.dto;

import lombok.Data;

import java.util.Date;

@Data
public class AgentProcessRegisterDto {
    private String agentName;
    private String agentType;
    private String agentId;
    private String advertiseIp;
    private Integer advertisePort;
    private Date startTime;

    /**
     * OAuth2 client id generated by the Reader itself. Optional only for a Reader that has not
     * upgraded yet; once present it cannot be rebound to another {@code agentId}.
     */
    private String clientId;
    /** Client secret generated by the Reader. Stored as a hash. */
    private String clientSecret;
}
